import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;

/**
 * Refuses every change a viewer asks for on a sheet: any request on a sheet other than a read is refused before
 * it reaches its handler, so it writes nothing. Loading the sheet and the bulk actions (which a viewer takes with
 * every selected item refused) are left to their handlers; see {@link ViewerGuardConfig}.
 */
@Component
public class ViewerGuard implements HandlerInterceptor {

    private final RoleService roles;

    public ViewerGuard(RoleService roles) {
        this.roles = roles;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String method = request.getMethod();
        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
            return true;
        }
        String user = request.getHeader("X-User");
        String sheetId = sheetId(request);
        if (user == null || sheetId == null) {
            return true;
        }
        if (roles.isViewer(sheetId, user.trim())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer cannot change anything on this sheet");
        }
        return true;
    }

    @SuppressWarnings("unchecked")
    private static String sheetId(HttpServletRequest request) {
        Object vars = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (!(vars instanceof Map<?, ?> map)) {
            return null;
        }
        Map<String, String> path = (Map<String, String>) map;
        return path.containsKey("sheetId") ? path.get("sheetId") : path.get("id");
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;

/**
 * Refuses every change asked for on an archived sheet: any request on it other than a read is refused before it
 * reaches its handler, so it writes nothing. Loading the sheet and the bulk actions (taken with every selected item
 * refused) are left to their handlers; see {@link ArchiveGuardConfig}.
 */
@Component
public class ArchiveGuard implements HandlerInterceptor {

    private final SheetService sheets;

    public ArchiveGuard(SheetService sheets) {
        this.sheets = sheets;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String method = request.getMethod();
        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
            return true;
        }
        String sheetId = sheetId(request);
        if (sheetId != null && sheets.isArchived(sheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived: nothing on it can change");
        }
        return true;
    }

    @SuppressWarnings("unchecked")
    private static String sheetId(HttpServletRequest request) {
        Object vars = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (!(vars instanceof Map<?, ?> map)) {
            return null;
        }
        Map<String, String> path = (Map<String, String>) map;
        return path.containsKey("sheetId") ? path.get("sheetId") : path.get("id");
    }
}
package net.officefloor.hq.app.history;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.servlet.HandlerInterceptor;

/**
 * Refuses every change asked for from a screen showing a sheet as of a date (one sending the
 * {@link SheetHistory#AS_OF_HEADER}): any request on a sheet other than a read is refused before it reaches its
 * handler, so it writes nothing. Loading the sheet is left to its handler; see {@link AsOfGuardConfig}.
 */
@Component
public class AsOfGuard implements HandlerInterceptor {

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String method = request.getMethod();
        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
            return true;
        }
        String asOf = request.getHeader(SheetHistory.AS_OF_HEADER);
        if (asOf != null && !asOf.isBlank()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The sheet is shown as of " + asOf.trim() + ": nothing on it can change");
        }
        return true;
    }
}

